import 'package:flutter/material.dart';
class DotsAndBoxesGame extends StatefulWidget{const DotsAndBoxesGame({super.key});@override State<DotsAndBoxesGame> createState()=>_DotsAndBoxesGameState();}
class _DotsAndBoxesGameState extends State<DotsAndBoxesGame>{final h=<String>{},v=<String>{};int score=0;void edge(String k,bool horizontal){final s=horizontal?h:v;if(s.contains(k))return;setState(()=>s.add(k));if(horizontal)setState(()=>score++);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Dots & Boxes')),body:Column(children:[Text('النقاط: $score',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w800)),Expanded(child:GridView.builder(itemCount:16,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:4),itemBuilder:(_,i){final r=i~/4,col=i%4;return Stack(children:[Center(child:Container(width:8,height:8,decoration:const BoxDecoration(shape:BoxShape.circle))),if(col<3)Positioned(right:0,top:0,bottom:0,width:12,child:GestureDetector(onTap:()=>edge('$r-$col-v',false),child:Container(color:v.contains('$r-$col-v')?Theme.of(c).colorScheme.primary:Theme.of(c).colorScheme.surfaceContainerHighest))),if(r<3)Positioned(left:0,right:0,bottom:0,height:12,child:GestureDetector(onTap:()=>edge('$r-$col-h',true),child:Container(color:h.contains('$r-$col-h')?Theme.of(c).colorScheme.primary:Theme.of(c).colorScheme.surfaceContainerHighest))) ]);}))))]));}